INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'fr-b2g-chorus', id, '2020-01-01', 1, 'https://chorus-pro.gouv.fr' FROM countries WHERE name_en = 'France';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-b2g-chorus', 'en', 'B2G e-invoicing mandatory via Chorus Pro', 'All suppliers to French public sector entities have been required to submit invoices electronically through Chorus Pro since 2020, ahead of the much larger B2B reform.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'fr-pa-critical-mass', id, '2026-01-01', 1, 'https://chorus-pro.gouv.fr' FROM countries WHERE name_en = 'France';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-pa-critical-mass', 'en', 'Platform accreditation network reaches critical mass', 'Over 100 Plateformes Agréées (PA) had received DGFiP accreditation by this point, giving businesses a genuine choice of certified provider ahead of the September go-live.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'fr-finance-law-2026', id, '2026-02-19', 1, 'https://chorus-pro.gouv.fr' FROM countries WHERE name_en = 'France';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-finance-law-2026', 'en', 'Finance Law formally renames PDP to PA and clarifies penalties', 'Article 123 of the Finance Law for 2026 (Law No. 2026-103) renamed "Plateforme de Dématérialisation Partenaire (PDP)" to "Plateforme Agréée (PA)" and amended CGI Articles 289 bis, 289 E, 290, 1737 and 1788 D to set clearer, higher penalties for non-compliance.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'fr-receive', id, '2026-09-01', 0, 'https://chorus-pro.gouv.fr' FROM countries WHERE name_en = 'France';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-receive', 'en', 'Receiving mandate + issuing for large/medium businesses', 'All VAT-registered businesses in France must be able to receive e-invoices; large and medium-sized businesses must also issue them via the public portal (PPF) or an accredited platform (PA, formerly PDP).', '["Register your business directory entry with the PPF (Portail Public de Facturation)", "Choose an accredited Plateforme Agr\u00e9\u00e9e or use the free public portal", "Set up e-reporting for B2C and cross-border transactions alongside e-invoicing"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'fr-issue-all', id, '2027-09-01', 0, 'https://chorus-pro.gouv.fr' FROM countries WHERE name_en = 'France';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-issue-all', 'en', 'Issuing mandate extends to all remaining businesses', 'Small and micro-enterprises, including freelancers, must issue e-invoices, completing France''s phased B2B e-invoicing and e-reporting reform.', '["Finalize invoicing software or PA integration well ahead of the deadline", "Confirm your software supports Factur-X, UBL, or CII format"]');
